  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:smartcityhub:apps:data_store_backend:application_settings:v1",
  "title": "Data Store application settings",
  "description": "Configuration schema for the Data Store service. The schema is intended for the fully resolved configuration after merging src/appsettings.json, optional environment-specific override files, and environment variables.",
  "type": "object",
  "properties": {
    "api": {
      "type": "object",
      "description": "Runtime metadata that is typically injected via environment variables instead of the base appsettings.json file.",
      "properties": {
        "environment": {
          "type": "string",
          "description": "Deployment environment suffix used to select optional override files. This value is usually provided through the API__ENVIRONMENT environment variable.",
          "minLength": 1,
          "examples": [
            "LOCAL",
            "COMPOSE",
            "COMPOSE_ALL",
            "UNIT_TESTS"
          ]
        }
      },
      "required": [
        "environment"
      ]
    },
    "fast_api": {
      "type": "object",
      "description": "HTTP API and CORS settings for the FastAPI application.",
      "properties": {
        "cors_middleware": {
          "type": "object",
          "description": "CORS middleware settings applied to Data Store endpoints.",
          "properties": {
            "cors_origins": {
              "type": "array",
              "description": "List of allowed CORS origins. Use full origins such as https://example.org, not paths.",
              "items": {
                "type": "string",
                "minLength": 1
